/* @lc app=leetcode id=2039 lang=kotlin */ class Solution { fun networkBecomesIdle(edges: Array<IntArray>, patience: IntArray): Int = patience.size.let { n -> edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { dist -> generateSequence(listOf(0).onEach { dist[it] = 0 } to 0) { (f, lv) -> f.flatMap { g[it].orEmpty() }.filter { dist[it] == -1 }.distinct().onEach { dist[it] = lv + 1 }.takeIf { it.isNotEmpty() }?.let { it to lv + 1 } }.count() }.let { dist -> (1 until n).maxOf { i -> (dist[i] * 2).let { d -> d + (d - 1) / patience[i] * patience[i] + 1 } } } } } }